// Tests for the engine inside index.html (DATA + CALC blocks). Run: node tests/test-calc.mjs
// Expected values come from the spec ../01-สเปกกติกาคำนวณ.md section 9 (generated by a separate Python script).
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
import assert from 'node:assert/strict';
import { loadEngine } from './run-engine.mjs';

const here = dirname(fileURLToPath(import.meta.url));
const api = loadEngine();
const NOTES = JSON.parse(readFileSync(join(here, 'expected-notes.json'), 'utf8'));
const SAFE = /^[\t\n\x20-\x7E฀-๿]*$/;

let pass = 0, fail = 0, checks = 0;
function test(name, fn) {
  try { fn(); pass++; console.log('ok   ' + name); }
  catch (e) { fail++; console.log('FAIL ' + name + '\n     ' + e.message); }
}
const eq = (a, b, msg) => { checks++; assert.deepEqual(a, b, msg); };
const reg = (w, age = 45) => {
  const r = api.regimen(age, w);
  if (!r.ok) throw new Error(`regimen(${age}, ${w}) did not compute: ${r.reason}`); // a designed case that fails to compute must fail the test
  return r;
};
const brief = r => Object.fromEntries(Object.entries(r.drugs).map(([c, x]) => [c, [x.dose, x.tabs, x.mgkg]]));

/* ---------- spec 9.1: 8 weights ---------- */
const T91 = {
  '30.0': { m: 'calc', d: { H: [200, { 100: 2 }, '6.7'], R: [300, { 300: 1 }, '10.0'], Z: [1000, { 500: 2 }, '33.3'], E: [500, { 500: 1 }, '16.7'] } },
  '35.0': { m: 'row1', d: { H: [300, { 100: 3 }, '8.6'], R: [450, { 450: 1 }, '12.9'], Z: [1000, { 500: 2 }, '28.6'], E: [800, { 400: 2 }, '22.9'] } },
  '49.5': { m: 'row1', d: { H: [300, { 100: 3 }, '6.1'], R: [450, { 450: 1 }, '9.1'], Z: [1000, { 500: 2 }, '20.2'], E: [800, { 400: 2 }, '16.2'] } },
  '50.0': { m: 'row2', d: { H: [300, { 100: 3 }, '6.0'], R: [600, { 300: 2 }, '12.0'], Z: [1500, { 500: 3 }, '30.0'], E: [1000, { 500: 2 }, '20.0'] } },
  '69.9': { m: 'row2', d: { H: [300, { 100: 3 }, '4.3'], R: [600, { 300: 2 }, '8.6'], Z: [1500, { 500: 3 }, '21.5'], E: [1000, { 500: 2 }, '14.3'] } },
  '70.0': { m: 'row3', d: { H: [300, { 100: 3 }, '4.3'], R: [600, { 300: 2 }, '8.6'], Z: [2000, { 500: 4 }, '28.6'], E: [1200, { 400: 3 }, '17.1'] } },
  '80.5': { m: 'row3', d: { H: [300, { 100: 3 }, '3.7'], R: [600, { 300: 2 }, '7.5'], Z: [2000, { 500: 4 }, '24.8'], E: [1200, { 400: 3 }, '14.9'] } },
  '100.5': { m: 'row3', d: { H: [300, { 100: 3 }, '3.0'], R: [600, { 300: 2 }, '6.0'], Z: [2000, { 500: 4 }, '19.9'], E: [1200, { 400: 3 }, '11.9'] } },
};
const strKeys = o => Object.fromEntries(Object.entries(o).map(([k, v]) => [String(k), v]));
for (const [w, exp] of Object.entries(T91)) {
  test(`9.1 ${w} kg doses, tablets, mg/kg (${exp.m})`, () => {
    const r = reg(w);
    eq(r.method, exp.m);
    for (const c of ['H', 'R', 'Z', 'E']) eq(brief(r)[c], [exp.d[c][0], strKeys(exp.d[c][1]), exp.d[c][2]], `${w} ${c}`);
  });
}
test('9.1 flags: 30 kg H and Z have no whole-tablet dose in range (yellow, other choice listed)', () => {
  const r = reg('30.0');
  eq([r.drugs.H.flag, r.drugs.H.nowhole, r.drugs.H.alt], ['yellow', true, [100]]);
  eq([r.drugs.Z.flag, r.drugs.Z.nowhole, r.drugs.Z.alt], ['yellow', true, [500]]);
  eq([r.drugs.R.flag, r.drugs.E.flag], [null, null]);
});
test('9.1 flags: table rows 35 to 70 kg never warn', () => {
  for (const w of ['35.0', '49.5', '50.0', '69.9', '70.0']) for (const c of ['H', 'R', 'Z', 'E']) eq(reg(w).drugs[c].flag, null, `${w} ${c}`);
});
test('9.1 flags: 80.5 kg E blue with suggestion 1,300; H R at maximum without warning', () => {
  const r = reg('80.5');
  eq([r.drugs.E.flag, r.drugs.E.suggest], ['blue', 1300]);
  eq(api.tabsMap('E', 1300), { 400: 2, 500: 1 });
  eq([r.drugs.H.atmax, r.drugs.R.atmax, r.drugs.H.flag, r.drugs.R.flag, r.drugs.Z.flag], [true, true, null, null, null]);
});
test('9.1 flags: 100.5 kg Z already at maximum 2,000 (no warning), E blue suggest 1,600', () => {
  const r = reg('100.5');
  eq([r.drugs.Z.flag, r.drugs.Z.suggest, r.drugs.Z.atmax], [null, null, true]);
  eq([r.drugs.E.flag, r.drugs.E.suggest], ['blue', 1600]);
});
test('5.2 first weights where row 3 drops below range: E blue at 80.3, Z reaches maximum at 100.3', () => {
  eq([reg('80.2').drugs.E.flag, reg('80.3').drugs.E.flag], [null, 'blue']);
  eq([reg('100.2').drugs.Z.atmax, reg('100.3').drugs.Z.atmax, reg('100.3').drugs.Z.flag], [false, true, null]);
});
test('10.11 suggestions never pass the maximum: Z none, E at most 1,600 (every weight 70.0 to 200.0)', () => {
  let n = 0;
  for (let w10 = 700; w10 <= 2000; w10++) {
    const r = reg(`${Math.floor(w10 / 10)}.${w10 % 10}`);
    assert.equal(r.drugs.Z.suggest, null, `Z ${w10}`);
    assert.ok(r.drugs.E.suggest == null || r.drugs.E.suggest <= 1600, `E ${w10}`);
    n++;
  }
  checks += n;
  eq([reg('107.0').drugs.E.suggest, reg('107.1').drugs.E.suggest, reg('150.0').drugs.E.suggest], [1600, 1600, 1600]);
  eq([api.mgkg10(1600, 1070), api.mgkg10(1600, 1071)], [150, 149]);
});

/* ---------- spec 9.2: adjust pairs ---------- */
const T92 = [
  ['48.0', '52.0', 'intensive', 'adjust', ['R', 'Z', 'E'], { R: [450, 600], Z: [1000, 1500], E: [800, 1000] }],
  ['69.0', '71.0', 'intensive', 'adjust', ['Z', 'E'], { Z: [1500, 2000], E: [1000, 1200] }],
  ['69.0', '71.0', 'continuation', 'same', [], {}],
  ['52.0', '53.5', 'intensive', 'same', [], {}],
  ['34.0', '36.0', 'intensive', 'adjust', ['H', 'R', 'E'], { H: [200, 300], R: [300, 450], E: [500, 800] }],
];
for (const [a, b, ph, res, changed, pairs] of T92) {
  test(`9.2 ${a} -> ${b} ${ph} = ${res}`, () => {
    const r = api.adjust(45, a, b, ph, null);
    eq([r.ok, r.result, r.changed], [true, res, changed]);
    for (const [c, [o, n]] of Object.entries(pairs)) eq([r.old[c], r.new[c]], [o, n], c);
  });
}
test('6 adjust uses the dose actually taken when given (current)', () => {
  const r = api.adjust(45, '52.0', '53.0', 'continuation', { H: 300, R: 450 });
  eq([r.result, r.changed, r.old.R, r.new.R], ['adjust', ['R'], 450, 600]);
});

/* ---------- spec 9.3: calendar dates ---------- */
const T93 = [
  ['2026-11-08', '2027-01-07', 61, '2027-01-08', '2027-05-07', 120],
  ['2026-12-31', '2027-02-28', 60, '2027-03-01', '2027-06-30', 122],
  ['2028-02-29', '2028-04-28', 60, '2028-04-29', '2028-08-28', 122],
  ['2027-08-31', '2027-10-30', 61, '2027-10-31', '2028-02-29', 122],
];
for (const [s, e2, di, c1, e6, dc] of T93) {
  test(`9.3 dates from ${s}`, () => {
    const d = api.dates(s);
    eq([d.end_intensive, d.days_intensive, d.start_continuation, d.end_treatment, d.days_continuation], [e2, di, c1, e6, dc]);
  });
}
test('9.3 month ends from 2026-12-31 (31 Jan -> 30 Jan, 31 Feb -> 1 Mar so end is 28 Feb)', () => {
  eq(api.dates('2026-12-31').month_end, ['2027-01-30', '2027-02-28', '2027-03-30', '2027-04-30', '2027-05-30', '2027-06-30']);
});
test('7.1 every start date 2024 to 2035: intensive 59 to 62 days, continuation 120 to 123, no gap between phases', () => {
  let d = { y: 2024, m: 1, d: 1 }, n = 0;
  const seenI = new Set(), seenC = new Set();
  while (d.y < 2036) {
    const iso = `${d.y}-${String(d.m).padStart(2, '0')}-${String(d.d).padStart(2, '0')}`;
    const r = api.dates(iso);
    seenI.add(r.days_intensive); seenC.add(r.days_continuation);
    const next = new Date(Date.UTC(r._e2.y, r._e2.m - 1, r._e2.d + 1));
    assert.equal(`${next.getUTCFullYear()}-${String(next.getUTCMonth() + 1).padStart(2, '0')}-${String(next.getUTCDate()).padStart(2, '0')}`, r.start_continuation, iso);
    const t = new Date(Date.UTC(d.y, d.m - 1, d.d + 1)); d = { y: t.getUTCFullYear(), m: t.getUTCMonth() + 1, d: t.getUTCDate() }; n++;
  }
  checks += n;
  eq([...seenI].sort(), [59, 60, 61, 62]);
  eq([...seenC].sort(), [120, 121, 122, 123]);
});

/* ---------- inputs (spec 5.3) ---------- */
test('5.3 age 15 not supported, 16 supported; age checked before weight', () => {
  eq(api.regimen(15, '52.0'), { ok: false, reason: 'age' });
  eq(reg('52.0', 16).ok, true);
  eq(api.regimen(15, 'abc').reason, 'age');
});
test('5.3 weight range 20.0 to 200.0 and at most 1 decimal', () => {
  eq(api.regimen(45, '19.9').reason, 'weight');
  eq(reg('20.0').ok, true);
  eq(reg('200.0').ok, true);
  eq(api.regimen(45, '200.1').reason, 'weight');
  eq(api.regimen(45, '52.25').reason, 'decimal');
  eq(api.regimen(45, '52.20').reason, 'decimal');
  eq(api.regimen(45, 'abc').reason, 'decimal');
  eq(api.regimen(45, '').reason, 'decimal');
  eq(api.regimen(45, '12345').reason, 'weight');
  eq(reg('52').drugs, reg('52.0').drugs);
});

/* ---------- pharmacist edits (spec 2, 5.2) ---------- */
test('5.2 edited doses: above cap red, above range yellow, below range blue, at cap below range no flag', () => {
  eq(api.editFlag('H', 400, 520), 'red');
  eq(api.editFlag('R', 750, 700), 'red');
  eq(api.editFlag('Z', 2000, 520), 'yellow');
  eq(api.editFlag('E', 400, 520), 'blue');
  eq(api.editFlag('H', 300, 800), null);
  eq(api.editFlag('E', 1000, 520), null);
  eq(api.editFlag('Z', 2500, 1200), 'red');
  eq(api.editFlag('E', 1700, 1200), 'red');
  eq(api.editFlag('E', 1600, 1500), null);
  eq(api.editFlag('Z', 2000, 1500), null);
});
test('8.1 edited dose gets "(เภสัชปรับจากตาราง)" in the note; unchanged edit does not', () => {
  const r = reg('80.5');
  const plan = api.planFrom(r, { E: { 400: 2, 500: 1 }, H: { 100: 3 } });
  eq([plan.doses.E.dose, plan.doses.E.edited, plan.doses.H.edited], [1300, true, false]);
  const note = api.buildStartNote(plan, '2026-11-08');
  assert.ok(note.includes('- Ethambutol 400 mg 2 tab + 500 mg 1 tab oral วันละครั้ง = 1,300 mg (16.1 mg/kg) (เภสัชปรับจากตาราง)'), note);
  assert.ok(!note.includes('Isoniazid 100 mg 3 tab oral วันละครั้ง = 300 mg (3.7 mg/kg) (เภสัชปรับ'), note);
  checks += 2;
});

/* ---------- notes, locked line by line (spec 9.4 to 9.8) ---------- */
test('9.4 Pharmacist note start, 52.0 kg from 8 Nov 2569', () => {
  const p = NOTES.start_note;
  eq(api.buildStartNote(api.planFrom(reg(p.weight, p.age), null), p.start), p.text);
});
test('9.5 nurse message start', () => {
  const p = NOTES.start_line;
  eq(api.buildStartLine(api.planFrom(reg(p.weight, p.age), null), p.start), p.text);
});
for (const k of ['adjust_note_change', 'adjust_note_same']) {
  test(`9.6/9.7 Pharmacist note ${k}`, () => {
    const p = NOTES[k];
    const adj = api.adjust(p.age, p.old, p.new, p.phase, null);
    eq(api.buildAdjustNote(adj, p.phase, api.planFrom(adj.to, null), p.when), p.text);
  });
}
test('9.8 nurse message adjust', () => {
  const p = NOTES.adjust_line_change;
  const adj = api.adjust(p.age, p.old, p.new, p.phase, null);
  eq(api.buildAdjustLine(adj, p.phase, api.planFrom(adj.to, null)), p.text);
});
test('8.1 every note for every weight 20.0 to 200.0 is ASCII + Thai only, no undefined/NaN', () => {
  let n = 0;
  for (let w10 = 200; w10 <= 2000; w10++) {
    const w = `${Math.floor(w10 / 10)}.${w10 % 10}`;
    const plan = api.planFrom(reg(w), null);
    for (const t of [api.buildStartNote(plan, '2026-11-08'), api.buildStartLine(plan, '2026-11-08')]) {
      assert.ok(SAFE.test(t) && !/undefined|NaN|Infinity|null/.test(t), `${w}: ${t}`); n++;
    }
    const adj = api.adjust(45, '52.0', w, 'intensive', null);
    const np = api.planFrom(adj.to, null);
    for (const t of [api.buildAdjustNote(adj, 'intensive', np, '2026-12-08'), api.buildAdjustLine(adj, 'intensive', np)]) {
      assert.ok(SAFE.test(t) && !/undefined|NaN|Infinity|null/.test(t), `${w}: ${t}`); n++;
    }
  }
  checks += n;
  assert.ok(n === 1801 * 4, `checked ${n}`);
});

console.log(`\n${pass} passed, ${fail} failed, ${checks} checks`);
process.exit(fail ? 1 : 0);
